// Extract confidence, calculate metrics, determine escalation.
// DEFENSIVE: if the upstream Email Formatter's Structured Output Parser2
// fails (LLM returns malformed JSON), Email Formatter has
// onError: 'continueRegularOutput' and emits { error: '...' } instead of
// the expected { output: { greeting, mainContent, ... } } shape. Without
// this guard the whole workflow crashes here and the customer gets no reply.
const upstream = $input.first().json || {};
const parserFailed = !upstream.output || !!upstream.error;

let greeting, mainContent, closing, footer, confidence, confidenceScore, references, detectedTone;

if (parserFailed) {
  // Safe fallback — generic apology + force escalation so a human follows up.
  greeting = 'Hello,';
  mainContent = 'Thank you for reaching out. We received your message but ran into a brief issue processing it automatically. A member of our support team has been notified and will follow up with you shortly.';
  closing = 'Best regards,';
  footer = 'This is an automated response. A human agent has been notified and will reach out shortly.';
  confidence = 'LOW';
  confidenceScore = 0; // <= 0.5 triggers the escalation branch in 'Check if Escalation Needed'
  references = [];
  detectedTone = 'neutral';
} else {
  const out = upstream.output;
  greeting = out.greeting;
  mainContent = out.mainContent;
  closing = out.closing;
  footer = out.footer;
  confidence = out.confidence;
  confidenceScore = out.confidenceScore;
  references = out.references;
  detectedTone = out.detectedTone;
}

const timestampStart = $('Format Current Email Data').first().json.startTime;
const timestampReceived = $('Format Current Email Data').first().json.receivedTime;
const timestampEnd = new Date().toISOString();
const responseTime = (new Date(timestampEnd).getTime() - new Date(timestampStart).getTime()) / 1000;

// Trust the LLM Human Escalation Detection classifier as the single source of truth.
// If upstream parsing failed, force escalation so a human picks it up.
const isEscalated = parserFailed || $('If').first().json.output.humanEscalation === true;

const wordCount = (mainContent || '').split(/\s+/).filter(Boolean).length;
const query = $('Format Current Email Data').first().json.chatInput;
const threadId = $('Format Current Email Data').first().json.threadId;
const channel = $('Format Current Email Data').first().json.channel;

return {
  json: {
    greeting: greeting,
    response: mainContent,
    closing: closing,
    footer: footer,
    references: references,
    detectedTone: detectedTone,
    confidence: confidence,
    confidenceScore: confidenceScore,
    isEscalated: isEscalated,
    responseTime: responseTime.toFixed(2),
    wordCount: wordCount,
    query: query,
    threadId: threadId,
    channel: channel,
    timestampReceived: timestampReceived,
    timestampStart: timestampStart,
    timestampEnd: timestampEnd,
    parserFailed: parserFailed
  }
};

