// Get all Sheets rows
const sheetRows = $input.all();

// ===== CHECK FOR EMPTY HISTORY (includes empty objects!) =====
// Google Sheets returns [{}] when no results, not []
if (sheetRows.length === 0 || 
    !sheetRows[0]?.json || 
    Object.keys(sheetRows[0].json).length === 0) {

  return { 
    json: { 
      conversationHistory: '', 
      messageCount: 0,
      lastEscalated: false
    } 
  };
}

// ===== FILTER OUT EMPTY OBJECTS (double safety) =====
const validRows = sheetRows.filter(row => 
  row.json && Object.keys(row.json).length > 0
);

if (validRows.length === 0) {
  return { 
    json: { 
      conversationHistory: '', 
      messageCount: 0,
      lastEscalated: false
    } 
  };
}

// ===== SORT CHRONOLOGICALLY (oldest first) =====
const sortedRows = validRows.sort((a, b) => {
  const timeA = new Date(a.json.timestampReceived || a.json.timestampStart || 0);
  const timeB = new Date(b.json.timestampReceived || b.json.timestampStart || 0);
  return timeA.getTime() - timeB.getTime();
});

// ===== BUILD CONVERSATION HISTORY =====
let conversationHistory = '';
let messageIndex = 1;

sortedRows.forEach((row) => {
  const data = row.json;

  const userTimestamp = data.timestampReceived || data.timestampStart || new Date().toISOString();
  const aiTimestamp = data.timestampEnd || new Date().toISOString();

  const userDate = new Date(userTimestamp);
  const aiDate = new Date(aiTimestamp);

  const userDateStr = isNaN(userDate.getTime()) ? 'Date unavailable' : userDate.toLocaleString();
  const aiDateStr = isNaN(aiDate.getTime()) ? 'Date unavailable' : aiDate.toLocaleString();

  // User message
  conversationHistory += `[Message ${messageIndex}]
From: Customer
Date: ${userDateStr}
Content: ${data.query || '[No content]'}

---

`;
  messageIndex++;

  // AI or human response — label by humanAgentReply flag
  const isHumanReply = data.humanAgentReply === 'True' || data.humanAgentReply === true;
  const responderLabel = isHumanReply ? 'Human Support Agent' : 'AI Customer Support Team';
conversationHistory += `[Message ${messageIndex}]
From: ${responderLabel}
Date: ${aiDateStr}
Content: ${data.response || '[No response]'}

---

`;
  messageIndex++;
});

// ===== CLEAN UP =====
conversationHistory = conversationHistory.trim();
if (conversationHistory.endsWith('---')) {
  conversationHistory = conversationHistory.slice(0, -3).trim();
}

// ===== GET LAST ESCALATED =====
const lastRow = sortedRows[sortedRows.length - 1]?.json || {};
const lastEscalated = lastRow.isEscalated || false;

// ===== RETURN DATA =====
return {
  json: {
    conversationHistory: conversationHistory,
    messageCount: sortedRows.length * 2,
    lastEscalated: lastEscalated
  }
};

// ===== GET THREAD DATA =====
const threadData = $('Get a thread').first().json;
const threadMessages = threadData.messages || [];

// AI email for filtering
const AI_EMAIL = 'your-email@example.com';

// ===== FILTER TO GET ONLY USER MESSAGES =====
const userMessages = threadMessages.filter(msg => {
  const msgFrom = msg.From || '';
  const emailMatch = msgFrom.match(/<([^>]+)>/);
  const msgSenderEmail = emailMatch ? emailMatch[1] : msgFrom;

  return msgSenderEmail.toLowerCase() !== AI_EMAIL.toLowerCase();
});

// Sort USER messages by date (oldest to newest)
const sortedUserMessages = userMessages.sort((a, b) => {
  return parseInt(a.internalDate) - parseInt(b.internalDate);
});

// Safety check
if (sortedUserMessages.length === 0) {
  throw new Error('No user messages found in thread');
}

// ===== GET CURRENT (LAST) USER MESSAGE =====
const lastUserMessage = sortedUserMessages[sortedUserMessages.length - 1];

// Extract sender info from FIRST user message
const fromField = userMessages[0].From;
const emailMatch = fromField.match(/<([^>]+)>/);
const senderEmail = emailMatch ? emailMatch[1] : fromField;
const subject = userMessages[0].Subject;

// ===== CLEAN MESSAGE BODY (remove quoted text) =====
let chatInput = lastUserMessage.text || lastUserMessage.snippet || '';

// Remove quoted text patterns
chatInput = chatInput.split(/On\s+\w+,\s+\d+\s+\w+\s+\d+\s+at\s+\d+:\d+/i)[0].trim();

if (chatInput.includes('wrote:')) {
  chatInput = chatInput.split('wrote:')[0].trim();
}

// Remove lines starting with ">"
chatInput = chatInput
  .split('\n')
  .filter(line => !line.trim().startsWith('>'))
  .join('\n')
  .trim();

// Remove HTML entities
chatInput = chatInput
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&amp;/g, '&')
  .replace(/&quot;/g, '"');

// Strip n8n test-sender footer ("--- This email was sent automatically with n8n").
// Without this, empty-body test emails carry the footer through and look non-empty
// to downstream classifiers.
chatInput = chatInput.split(/\n?---\s*\n?/)[0].trim();
chatInput = chatInput
  .replace(/This email was sent automatically with n8n\.?$/i, '')
  .trim();

// ===== GET DATA FROM SHEETS HISTORY NODE =====
const sheetsHistory = $('Format Conversation History from Sheets').first().json;

// Extract values from Sheets
const conversationHistory = sheetsHistory.conversationHistory || '';
const previousMessageCount = sheetsHistory.messageCount || 0; // Previous messages
const isEscalated = sheetsHistory.lastEscalated || false; // Renamed for clarity

// Calculate current state
const isFirstMessage = previousMessageCount === 0; // True if no previous messages
const messageCount = 1; // Always 1 - representing current user message

// ===== EDGE CASE DETECTION (Category 7 — Group A & B) =====
// Detect empty body, minimal input, very long body and inject directives
// for the AI Agent. This avoids adding new branches — the existing AI Agent
// can produce graceful clarification responses when given the right context.
const trimmedInput = (chatInput || '').trim();
const wordCount = trimmedInput ? trimmedInput.split(/\s+/).filter(Boolean).length : 0;
const charCount = trimmedInput.length;

const isEmptyBody = charCount === 0;
const isMinimalInput = !isEmptyBody && (wordCount <= 1 || charCount < 5);
const isLongEmail = wordCount > 800;

let edgeCaseFlag = null;
let originalChatInput = chatInput;
// For EMPTY_BODY and MINIMAL_INPUT: only set the flag here.
// The 'Route: Empty/Minimal?' node downstream will short-circuit the pipeline
// and send an immediate clarification reply, bypassing classification + AI Agent.
if (isEmptyBody) {
  edgeCaseFlag = 'EMPTY_BODY';
} else if (isMinimalInput) {
  edgeCaseFlag = 'MINIMAL_INPUT';
} else if (isLongEmail) {
  edgeCaseFlag = 'LONG_EMAIL';
  chatInput = `[INTERNAL DIRECTIVE — LONG EMAIL (${wordCount} words)] When deciding intent and confidence, focus on: (1) the customer's most recent question or request (typically the closing paragraph), (2) any explicit action keywords (escalate, refund, cancel, lawsuit, security breach, fraud, overheating), and (3) the sign-off context. Long context with a routine closing question is a routine question; long context with buried escalation signals must escalate. Original email follows:]\n\n${chatInput}`;
}

// ===== RETURN DATA =====
return {
  json: {
    // ===== Thread Identifiers =====
    threadId: threadData.id,
    messageId: lastUserMessage.id,

    // ===== Edge case flag for downstream nodes =====
    edgeCaseFlag: edgeCaseFlag,
    originalChatInput: originalChatInput,
    wordCount: wordCount,

    // ===== Current Message (from Gmail, possibly directive-wrapped) =====
    chatInput: chatInput,
    subject: subject,
    senderEmail: senderEmail,

    // ===== Conversation Context (from Sheets) =====
    conversationHistory: conversationHistory,

    // ===== Message Metadata =====
    messageCount: messageCount, // Current message count = 1
    isFirstMessage: isFirstMessage, // True if previousMessageCount === 0
    isEscalated: isEscalated, // Previous escalation status

    // ===== Timestamps =====
    startTime: new Date().toISOString(), // When workflow started
    receivedTime: new Date(parseInt(lastUserMessage.internalDate)).toISOString(), // When user sent email

    // ===== Channel =====
    channel: 'email'
  }
};

const rows = $input.all();

// Google Sheets returns [{}] on no match (confirmed in existing Format Conversation History code)
const validRows = rows.filter(row =>
  row.json && Object.keys(row.json).length > 0
);

const isReEscalation = validRows.some(row => {
  const isEsc = String(row.json.isEscalated ?? '').toLowerCase();
  const response = String(row.json.response ?? '').toLowerCase();
  return (isEsc === 'true') && response === 'pending';
});

return { json: { isReEscalation } };

// Read email data from Format Current Email Data (or Pack Summarized Data on long-email path).
// Don't read from $input — upstream is now Spam Filter (chainLlm) whose output replaces the data shape.
const fced = $('Format Current Email Data').first().json;
const isLongEmail = fced.edgeCaseFlag === 'LONG_EMAIL';
const data = isLongEmail
  ? $('Pack Summarized Data').first().json
  : fced;
const emailBody = (data.chatInput || '').toLowerCase()
  .replace(/i'm/g, 'i am')
  .replace(/can't/g, 'cannot')
  .replace(/it's/g, 'it is')
  .replace(/don't/g, 'do not')
  .replace(/won't/g, 'will not')
  .replace(/i've/g, 'i have')
  .replace(/i'd/g, 'i would')
  .replace(/i'll/g, 'i will');

// KEYWORDS THAT ALWAYS TRIGGER ESCALATION (no context check needed)
// Multilingual additions for Category 7 Group C (TC588 — German cancel/legal terms missed in round 1)
const alwaysEscalate = [
  // English - legal/fraud
  'lawyer', 'legal action', 'fraud', 'chargeback', 'sue', 'court', 'lawsuit',
  // Regulatory / Media / Executive threats (KB 05_Escalation_Guidelines Section 2)
  'attorney general', 'consumer protection', 'bbb', 'better business bureau',
  'fda complaint', 'fcc complaint', 'filed a complaint', 'complaint filed',
  'reporter', 'journalist', 'news article', 'viral', 'going public',
  // Safety (KB 05_Escalation_Guidelines Section 2 Safety category) — multi-word forms to avoid false positives
  'overheating', 'fire risk', 'caught fire', 'catches fire', 'electric shock',
  'burning smell', 'safety hazard', 'physical injury', 'swollen battery',
  'product recall', 'dangerous',
  // Security beyond fraud (KB Section 2 Security category)
  'hacked', 'data breach', 'security breach', 'stolen', 'identity theft', 'unauthorized access',
  // German (Group C — TC588)
  'klage', 'anwalt', 'betrug', 'rechtlich',
  // Bosnian/Croatian (Group C — TC589)
  'tužba', 'prevara', 'odvjetnik', 'advokat',
  // Turkish (Group C — TC595)
  'dava', 'avukat', 'dolandırıcılık'
];

// KEYWORDS THAT NEED CONTEXT CHECK
// Multilingual additions for cancellation/refund intent
const contextKeywords = [
  // English
  'refund', 'cancel', 'charged', 'authorize', 'unauthorize',
  // German (TC588)
  'kündigen', 'kündigung', 'erstattung', 'rückerstattung',
  // Bosnian/Croatian
  'otkazati', 'povrat', 'naplata',
  // Turkish
  'iptal', 'ıade'
];

// INFORMATIONAL PATTERNS - if ANY of these appear alongside a context keyword,
// the email is likely a routine question and should NOT be escalated
const informationalPatterns = [
  // Question starters
  'how do i', 'how can i', 'can i', 'could i', 'is it possible',
  'is this possible', 'is there any way', 'is there a',
  'what is your', 'what is the', 'what are my', 'what could cause',
  'what happens if', 'what should i',
  // Timeline questions  
  'when will', 'when can i', 'how long', 'how far in advance',
  // Policy questions
  'will i get', 'will i receive', 'will i be', 'will there be',
  'do i need to', 'do i have to', 'am i eligible',
  'if i cancel', 'if i return',
  // Requests for guidance
  'walk me through', 'guide me', 'could you please explain',
  'can you tell me', 'please advise', 'could you advise',
  'i would like to', 'i want to make sure',
  // Confusion (not anger)
  'i am confused', 'i am not sure', 'i am quite confused',
  'i just realised', 'i just realized', 'i forgot to',
  // Preference/option exploration
  'instead of', 'rather than', 'prefer to', 'would prefer',
  'i do not want', 'i would prefer'
];

// DISPUTE PATTERNS - if ANY of these appear alongside a context keyword,
// the email IS a dispute and SHOULD be escalated
const disputePatterns = [
  // Emotional escalation
  'demand', 'unacceptable', 'furious', 'disgusted', 'livid',
  'outraged', 'incensed', 'appalled', 'fed up', 'done with',
  // Ultimatums
  'last chance', 'final warning', 'never again', 'or else',
  // Aggressive refund demands
  'i want my money', 'full refund now', 'give me back', 'refund immediately',
  'i demand a refund', 'right now or',
  // Threats
  'i will report', 'i will file', 'going public', 'social media'
];
// NOTE: "immediately" was REMOVED from disputePatterns because customers 
// often use it descriptively ("I immediately realised") not as a demand

// === DETECTION LOGIC ===

// Word-boundary matcher. Keywords are plain ascii words (no regex metachars),
// so no escape needed. This avoids 'sue' matching inside 'issue' / 'tissue' / 'pursue'.
const wordIncludes = (text, kw) => new RegExp('\\b' + kw + '\\b', 'i').test(text);

// Always escalate for legal/fraud keywords
const mustEscalate = alwaysEscalate.some(kw => wordIncludes(emailBody, kw));

// Check context keywords
const hasContextKeyword = contextKeywords.some(kw => wordIncludes(emailBody, kw));
const isInformational = informationalPatterns.some(p => emailBody.includes(p));
const isDispute = disputePatterns.some(p => emailBody.includes(p));

let shouldEscalate = false;

if (mustEscalate) {
  shouldEscalate = true;
} else if (hasContextKeyword && isDispute && !isInformational) {
  shouldEscalate = true;  // "cancel" + "furious" = escalate
} else if (hasContextKeyword && isInformational) {
  shouldEscalate = false;  // "how do I cancel" = AI handles
} else if (hasContextKeyword && !isInformational && !isDispute) {
  shouldEscalate = false;  // CHANGED: default to AI handles, let LLM decide later
}
// If no context keyword at all, shouldEscalate stays false (normal flow)

// Logging (word-boundary match for single-word keywords)
const detectedAlways = alwaysEscalate.filter(kw => wordIncludes(emailBody, kw));
const detectedContext = contextKeywords.filter(kw => wordIncludes(emailBody, kw));
const detectedInfo = informationalPatterns.filter(p => emailBody.includes(p));
const detectedDispute = disputePatterns.filter(p => emailBody.includes(p));

// Backward-compatible output
const hasPriorityKeyword = mustEscalate || (hasContextKeyword && isDispute && !isInformational);
const hasNegativeSentiment = isDispute;

return [{
  json: {
    ...data,
    hasPriorityKeyword,
    hasNegativeSentiment,
    detectedKeywords: [...detectedAlways, ...detectedContext],
    detectedInfoPatterns: detectedInfo,
    detectedDisputePatterns: detectedDispute,
    escalationFlag: shouldEscalate,
    originalEmailContent: data.chatInput || ''
  }
}];

