// ========================================================================
// SENDER ALLOWLIST FILTER — docx Section 5.1.7.5 #3 (Group E)
// ========================================================================
// Drops emails from senders not on the allowlist OR matching system/spoofed
// address patterns. Runs at the very start of the workflow before any
// thread/history fetching, classification, or LLM calls.
//
// To add an allowed sender: append to `allowedSenders` array.
// To add a blocked pattern: append to `blockedPatterns` array.
// ========================================================================

const fromField = ($input.first().json.From || '').toLowerCase();

// Allowlist — only emails from these senders are processed.
const allowedSenders = [
  'your-email@example.com',
  'your-email@example.com'
];

// Blocklist — system / automated / spoofed address patterns.
const blockedPatterns = [
  'noreply@',
  'no-reply@',
  'do-not-reply@',
  'mailer-daemon',
  'postmaster@',
  'bounces@',
  'notification@',
  'automated@'
];

const isAllowed = allowedSenders.some(s => fromField.includes(s.toLowerCase()));
const isBlocked = blockedPatterns.some(p => fromField.includes(p.toLowerCase()));

if (!isAllowed || isBlocked) {
  // Drop — returning [] halts downstream processing for this run.
  return [];
}

// Pass-through unchanged.
return $input.all();

// ========================================================================
// PACK SUMMARIZED DATA — docx Section 5.1.7.5 #5 (Group B — Long Email)
// ========================================================================
// Replaces chatInput with the LLM-generated summary while preserving every
// other field from Format Current Email Data. Downstream classifiers should
// use $json.chatInput (which becomes the summary on this branch) instead of
// referencing Format Current Email Data directly when on the long-email path.
// ========================================================================

const llmOutput = $input.first().json;
const fced = $('Format Current Email Data').first().json;

// chainLlm without an output parser returns the raw text under `text` (or
// occasionally under `output.text` depending on n8n version). Be defensive.
const summary = (typeof llmOutput === 'string')
  ? llmOutput
  : (llmOutput.text || llmOutput.output?.text || llmOutput.output || JSON.stringify(llmOutput));

return [{
  json: {
    ...fced,
    chatInput: summary,
    originalLongChatInput: fced.chatInput,
    wasSummarized: true
  }
}];

// Build the log payload for the EMPTY_BODY / MINIMAL_INPUT branch.
// This branch never reaches AI Agent / Email Formatter / Calculate Metrics nodes,
// so we synthesize the same shape of data 'Log Interaction to Sheets1' reads from $json.

const fmt = $('Format Current Email Data').first().json;

const subject = fmt.subject || '';
const originalInput = (fmt.originalChatInput || fmt.chatInput || '').trim();
const edgeCase = fmt.edgeCaseFlag || '';
const threadId = fmt.threadId || '';
const messageId = fmt.messageId || '';
const channel = fmt.channel || 'email';
const conversationHistory = fmt.conversationHistory || '';
const messageCount = fmt.messageCount || 1;

// Timestamps
const timestampReceived = fmt.receivedTime || '';
const timestampStart = fmt.startTime || '';
const timestampEnd = new Date().toISOString();

const startMs = timestampStart ? new Date(timestampStart).getTime() : null;
const endMs = new Date(timestampEnd).getTime();
const responseTime = (startMs && !isNaN(startMs))
  ? ((endMs - startMs) / 1000).toFixed(2)
  : '0.00';

// Reconstruct the clarification reply that 'Reply: Empty Body Clarification' just sent
const greeting = 'Hello,';
const mainContent = `Thank you for contacting us regarding "${subject || 'your inquiry'}". We received your email, but we couldn't find any details in the message body.\n\nTo help you effectively, could you please share:\n• What product or service you're contacting us about\n• The specific question or issue you need help with\n• Any relevant order or account number, if applicable\n\nWe'll be happy to assist as soon as we have more details.`;
const closing = 'Best regards,';
const footer = 'This is an automated response. If you would like to speak with a human representative, please mention this in your reply.';

const wordCount = mainContent.split(/\s+/).filter(Boolean).length;

// Build query field — log what came in, with edge-case marker
let query;
if (edgeCase === 'EMPTY_BODY') {
  query = `[EMPTY_BODY] subject="${subject}"`;
} else if (edgeCase === 'MINIMAL_INPUT') {
  query = `[MINIMAL_INPUT] "${originalInput}" subject="${subject}"`;
} else {
  query = originalInput || `[${edgeCase || 'NO_BODY'}] subject="${subject}"`;
}

return {
  json: {
    // Fields that 'Log Interaction to Sheets1' mapping reads via $json.X:
    greeting: greeting,
    response: mainContent,
    closing: closing,
    footer: footer,
    references: [],            // No KB used for clarification reply
    detectedTone: 'neutral',
    confidence: 'N/A',
    confidenceScore: 0,
    isEscalated: false,
    responseTime: responseTime,
    wordCount: wordCount,
    query: query,
    channel: channel,
    threadId: threadId,
    messageId: messageId,
